-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",      im.DEPT                                               AS \"Department Number\",     d.DEPT_NAME                                           AS \"Department Name\",     im.CLASS                                              AS \"Class Number\",     c.CLASS_NAME                                          AS \"Class Name\",     im.SUBCLASS                                           AS \"Subclass Number\",     sc.SUB_NAME                                           AS \"Subclass Name\",      im.ITEM                                               AS \"Pack Item ID\",     im.ITEM_DESC                                          AS \"Pack Item Description\",     im.PACK_IND                                           AS \"Pack Indicator\",     im.STANDARD_UOM                                       AS \"Pack Unit of Measure\",     im.STATUS                                             AS \"Item Status\",      pi.ITEM                                               AS \"Component Item ID\",     cim.ITEM_DESC                                         AS \"Component Item Description\",     pi.PACK_QTY                                           AS \"Component Quantity in Pack\",     cim.STANDARD_UOM                                      AS \"Component Unit of Measure\",      ril.LOCATION                                          AS \"Location ID\",     il.LOC_TYPE                                           AS \"Location Type\",     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS \"Location Type Description\",     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS \"Location Name\",     il.STATUS                                             AS \"Item Location Status\",     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS \"Item Location Status Description\",      isc.SUPPLIER                                          AS \"Supplier ID\",     sp.SUP_NAME                                           AS \"Supplier Name\",     sp.SUP_STATUS                                         AS \"Supplier Status\",     isc.ORIGIN_COUNTRY_ID                                 AS \"Origin Country\",     isc.PRIMARY_SUPP_IND                                  AS \"Primary Supplier Indicator\",     isc.PRIMARY_COUNTRY_IND                               AS \"Primary Country Indicator\",      isc.SUPP_PACK_SIZE                                    AS \"Supplier Pack Size\",     isc.INNER_PACK_SIZE                                   AS \"Inner Pack Size\",     isc.TI                                                AS \"Pallet Tier\",     isc.HI                                                AS \"Pallet High\",     (isc.TI * isc.HI * isc.SUPP_PACK_SIZE)               AS \"Pallet Order Multiple\",      CASE         WHEN isc.SUPP_PACK_SIZE BETWEEN 2  AND 5   THEN '2 - 5 Cases'         WHEN isc.SUPP_PACK_SIZE BETWEEN 6  AND 12  THEN '6 - 12 Cases'         WHEN isc.SUPP_PACK_SIZE BETWEEN 13 AND 24  THEN '13 - 24 Cases'         WHEN isc.SUPP_PACK_SIZE &gt; 24               THEN '25+ Cases'         ELSE 'Review'     END                                                   AS \"Pack Size Bucket\",      'USING GLOBAL DEFAULT'                                AS \"Pack Size Override Status\",      isc.SUPP_PACK_SIZE                                    AS \"Effective Supplier Pack Size\",     isc.INNER_PACK_SIZE                                   AS \"Effective Inner Pack Size\",      isc.UNIT_COST                                         AS \"Unit Cost\",     ROUND(isc.UNIT_COST * isc.SUPP_PACK_SIZE, 4)         AS \"Pack Total Cost\",     isc.PICKUP_LEAD_TIME                                  AS \"Pickup Lead Time\",      ril.REPL_METHOD                                       AS \"Replenishment Method\",     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS \"Replenishment Method Description\",     ril.STOCK_CAT                                         AS \"Stock Category\",     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS \"Stock Category Description\",     ril.REPL_ORDER_CTRL                                   AS \"Order Control\",     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'         ELSE ril.REPL_ORDER_CTRL     END                                                   AS \"Order Control Description\",     ril.MIN_STOCK                                         AS \"Minimum Stock\",     ril.MAX_STOCK                                         AS \"Maximum Stock\",     ril.REVIEW_CYCLE                                      AS \"Review Cycle\",     ril.SOURCE_WH                                         AS \"Source Warehouse\",     ril.PRIMARY_PACK_NO                                   AS \"Primary Replenishment Pack\",     ril.NON_SCALING_IND                                   AS \"Scaling Exempt Indicator\",     ril.MAX_SCALE_VALUE                                   AS \"Maximum Scale Amount\",      ils.STOCK_ON_HAND                                     AS \"Pack Current Stock on Hand\",     ils.AV_COST                                           AS \"Pack Weighted Average Cost\",      il.SELLING_UNIT_RETAIL                                AS \"Pack Unit Retail\",      cils.STOCK_ON_HAND                                    AS \"Component Current Stock on Hand\",      CASE         WHEN NVL(ril.MAX_STOCK, 0) &gt; 0              AND NVL(ils.STOCK_ON_HAND, 0) &lt; ril.MAX_STOCK         THEN CEIL(              (ril.MAX_STOCK - NVL(ils.STOCK_ON_HAND, 0))              / isc.SUPP_PACK_SIZE              ) * isc.SUPP_PACK_SIZE         ELSE 0     END                                                   AS \"Estimated Order Quantity\",      CASE         WHEN im.PACK_IND = 'Y'              AND isc.SUPP_PACK_SIZE &gt; 1         THEN 'REVIEW: Catch Weight WP recommends SUPP_PACK_SIZE=1 for simple packs'         ELSE 'MONITOR'     END                                                   AS recommendation  FROM     MFCS_RDS.RDS_WV_ITEM_MASTER             im      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  im.ITEM              = isc.ITEM                                                   AND  isc.PRIMARY_SUPP_IND = 'Y'                                                   AND  isc.PRIMARY_COUNTRY_IND = 'Y'                                                   AND  isc.SUPP_PACK_SIZE   &gt; 1      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC     ril  ON  im.ITEM              = ril.ITEM                                                   AND  ril.PRIMARY_REPL_SUPPLIER = isc.SUPPLIER                                                   AND  ril.REPL_METHOD    IS NOT NULL      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC           il  ON  ril.ITEM             = il.ITEM                                                   AND  ril.LOCATION        = il.LOC                                                   AND  il.LOC_TYPE         = ril.LOC_TYPE      JOIN  MFCS_RDS.RDS_WV_DEPS               d   ON  im.DEPT              = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS              c   ON  im.DEPT              = c.DEPT                                                   AND  im.CLASS             = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc  ON  im.DEPT              = sc.DEPT                                                   AND  im.CLASS             = sc.CLASS                                                   AND  im.SUBCLASS          = sc.SUBCLASS       LEFT JOIN MFCS_RDS.RDS_WV_PACKITEM       pi  ON  im.ITEM              = pi.PACK_NO      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_MASTER    cim ON  pi.ITEM              = cim.ITEM      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                   ON  im.ITEM              = iscl.ITEM                                                   AND  isc.SUPPLIER        = iscl.SUPPLIER                                                   AND  iscl.LOC            = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS           sp  ON  isc.SUPPLIER         = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE          st  ON  ril.LOCATION         = st.STORE                                                   AND  il.LOC_TYPE          = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH             wh  ON  ril.LOCATION         = wh.WH                                                   AND  il.LOC_TYPE          = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  ils  ON  im.ITEM              = ils.ITEM                                                   AND  ril.LOCATION        = ils.LOC                                                   AND  ils.LOC_TYPE        = ril.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils ON  pi.ITEM              = cils.ITEM                                                   AND  ril.LOCATION        = cils.LOC                                                   AND  cils.LOC_TYPE       = ril.LOC_TYPE  WHERE     im.PACK_IND          = 'Y'     AND isc.SUPP_PACK_SIZE &